import React, { useState } from "react";
import './grid.css';
import Row from "./row";

interface GridProps {
    word: string;
    guessNumber: number;
    guesses: string[];
    resultCode: string[];
}

const Grid: React.FC<GridProps> = ({word, guessNumber, guesses, resultCode}) => {
    return(
        <>
            <div className="gridcontainer">
                <Row word = {guessNumber === 0 ? word : guesses[0]} resultCode = {resultCode[0]}/>
                <Row word = {guessNumber === 1 ? word : guesses[1]} resultCode = {resultCode[1]}/>
                <Row word = {guessNumber === 2 ? word : guesses[2]} resultCode = {resultCode[2]}/>
                <Row word = {guessNumber === 3 ? word : guesses[3]} resultCode = {resultCode[3]}/>
                <Row word = {guessNumber === 4 ? word : guesses[4]} resultCode = {resultCode[4]}/>
                <Row word = {guessNumber === 5 ? word : guesses[5]} resultCode = {resultCode[5]}/>
            </div>
        </>
    );
}

export default Grid;
